export function periodBootMesh(input={}){const upper=input.continuationBootColor||'#795337',faces=shoeMesh('spikes',upper,upper,'#3e2d20',.13).map(f=>({...f,p:f.p.map(p=>[...p])}));
 const quad=(p,color,material='leather')=>faces.push({p,color,material,grain:1});for(let j=0;j<28;j++){const a=j/28*TAU,b=(j+1)/28*TAU,ring=(a,y,r)=>[-.96+Math.cos(a)*r,y,Math.sin(a)*r*.76];quad([ring(a,.54,.32),ring(a,1,.285),ring(b,1,.285),ring(b,.54,.32)],upper);quad([ring(a,1,.285),ring(a,1.03,.23),ring(b,1.03,.23),ring(b,1,.285)],'#5c3d28');quad([ring(a,1.03,.23),ring(a,.64,.23),ring(b,.64,.23),ring(b,1.03,.23)],'#34271e');}return faces;}
