export function paintPeriodBoot(c,pose={},input={}){const key=input.continuationBootColor||'#795337';if(key!==bootKey){bootKey=key;bootFaces=periodBootMesh(input);}const faces=bootFaces.map(f=>{const p=f.p.map(p=>rotatePoint(p,pose));return{...f,v:p,z:p.reduce((n,p)=>n+p[2],0)/p.length}}).sort((a,b)=>a.z-b.z),scale=(pose.size??280)/3;c.save();c.translate(pose.x??480,pose.y??300);c.globalAlpha*=pose.opacity??1;c.filter=(c.filter==='none'?'':c.filter+' ')+`blur(${pose.blur||0}px)`;for(const f of faces){const[a,b,d]=f.v,ab=b.map((v,i)=>v-a[i]),ad=d.map((v,i)=>v-a[i]),n=[ab[1]*ad[2]-ab[2]*ad[1],ab[2]*ad[0]-ab[0]*ad[2],ab[0]*ad[1]-ab[1]*ad[0]],len=Math.hypot(...n)||1,light=(.4+.55*Math.abs((n[0]*-.3+n[1]*.65+n[2]*.7)/len))*(pose.light??1);c.fillStyle='rgb('+rgb(f.color).map(v=>Math.round(clamp(v*light,0,255))).join(',')+')';c.beginPath();f.v.forEach(([x,y,z],i)=>{const p=6/(6-z*.17);i?c.lineTo(x*scale*p,-y*scale*p):c.moveTo(x*scale*p,-y*scale*p)});c.closePath();c.fill();}c.restore();}
