let ballCanvas,sphereCanvas;export function paintLeatherBall(c,time,x,y,r,input={}){if(r<=0)return;const m=c.getTransform(),xx=m.a*x+m.c*y+m.e,yy=m.b*x+m.d*y+m.f; r*=Math.hypot(m.a,m.b);x=xx;y=yy;ballCanvas??=Object.assign(document.createElement('canvas'),{width:960,height:540});const b=ballCanvas.getContext('2d'),data=b.createImageData(960,540),p=data.data,color=rgb(input.continuationBallColor||'#714731'),yaw=time*(input.continuationBallSpin??.45),left=Math.max(0,Math.floor(x-r)),right=Math.min(960,Math.ceil(x+r)),top=Math.max(0,Math.floor(y-r)),bottom=Math.min(540,Math.ceil(y+r));for(let Y=top;Y<bottom;Y++)for(let X=left;X<right;X++){const nx=(X+.5-x)/r,ny=(Y+.5-y)/r,rr=nx*nx+ny*ny;if(rr>1)continue;const nz=Math.sqrt(1-rr),u=(Math.atan2(nx,nz)+yaw)/Math.PI,v=Math.asin(ny)/Math.PI,stitch=Math.min(Math.abs(Math.sin(u*4*Math.PI)),Math.abs(Math.sin(v*4*Math.PI+Math.sin(u*3)*.4))),seam=stitch<.026?.42:stitch<.055?.72:1,grain=.95+.05*Math.sin(u*1200+v*730)*Math.sin(u*380-v*990),light=.35+.7*Math.max(0,-nx*.48-ny*.56+nz*.68),glint=Math.pow(Math.max(0,-nx*.28-ny*.5+nz*.82),35)*28,i=(Y*960+X)*4;for(let k=0;k<3;k++)p[i+k]=clamp(color[k]*light*seam*grain+glint,0,255);p[i+3]=Math.round(clamp((1-rr)*r*.8)*255);}b.putImageData(data,0,0);c.save();c.setTransform(1,0,0,1,0,0);c.drawImage(ballCanvas,0,0);c.restore();}
const photoTextures=new WeakMap();function photoData(im){if(!(im?.naturalWidth||im?.width))return null;const old=photoTextures.get(im);if(old?.src===im.src)return old;const iw=im.naturalWidth||im.width,ih=im.naturalHeight||im.height,w=Math.min(2048,iw),h=Math.round(w*ih/iw),cv=Object.assign(document.createElement('canvas'),{width:w,height:h}),c=cv.getContext('2d');c.drawImage(im,0,0,w,h);const result={src:im.src,width:w,height:h,data:c.getImageData(0,0,w,h).data};photoTextures.set(im,result);return result;}
