export function paintCoinStacks(c,time,progress,input={},offsetY=0){const count=Math.max(0,Math.min(100,Math.round(input.continuationCoinCount??48))),strength=clamp(progress);c.save();c.translate(0,offsetY);for(let i=0;i<count;i++){const row=Math.floor(i/12),col=i%12,x=90+col*70+Math.sin(i*5)*6,y=450+row*27,h=(3+Math.floor((Math.sin(i*17.7)*.5+.5)*12))*strength,rad=13+row*1.9,gold=i%4===0;for(let j=0;j<h;j++){const yy=y-j*3.4;c.fillStyle=gold?'#877048':'#6b7276';c.beginPath();c.ellipse(x,yy+2,rad,rad*.31,0,0,TAU);c.fill();const g=c.createLinearGradient(x-rad,yy-2,x+rad,yy+3);g.addColorStop(0,gold?'#a28a5c':'#99a0a2');g.addColorStop(.42,gold?'#e6d49d':'#e1e3df');g.addColorStop(.7,gold?'#a68a53':'#989c9a');g.addColorStop(1,gold?'#66532f':'#585e60');c.fillStyle=g;c.beginPath();c.ellipse(x,yy,rad,rad*.3,0,0,TAU);c.fill();c.strokeStyle=gold?'#e1cc8e66':'#f2f4ee55';c.lineWidth=.6;c.stroke();}}c.restore();}
